import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIAvatar from "UIAvatar.react";
import UILink from "UILink.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  row: { paddingTop: 4, paddingInlineStart: 4 },
  item: { marginInlineStart: -4, borderRadius: "50%", borderWidth: 2, borderStyle: "solid", borderColor: colors.cardBackground, lineHeight: 0 },
});

export default function ProfileFriendFacepile({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileFriendFacepile_user on User {
        friends(first: 8) {
          edges {
            node {
              id
              name
              url
              profile_picture(size: 32) {
                uri
              }
            }
          }
        }
      }
    `,
    user,
  );
  const edges = data.friends?.edges ?? [];
  return (
    <UIRow xstyle={styles.row} data-testid="profile-facepile">
      {edges.map((edge) =>
        edge?.node ? (
          <span key={edge.node.id} {...stylex.props(styles.item)}>
            <UILink href={edge.node.url} label={edge.node.name}>
              <UIAvatar src={edge.node.profile_picture?.uri} size={32} />
            </UILink>
          </span>
        ) : null,
      )}
    </UIRow>
  );
}
