import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIAvatar from "UIAvatar.react";

const styles = stylex.create({
  ring: { display: "inline-block", lineHeight: 0, borderRadius: "50%", borderWidth: 4, borderStyle: "solid", borderColor: colors.cardBackground, backgroundColor: colors.cardBackground },
});

export default function ProfileAvatarBlock({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileAvatarBlock_user on User {
        name
        is_online
        profile_picture(size: 168) {
          uri
        }
      }
    `,
    user,
  );
  return (
    <span data-testid="profile-avatar" {...stylex.props(styles.ring)}>
      <UIAvatar src={data.profile_picture?.uri} size={168} label={data.name ?? ""} online={data.is_online ?? false} />
    </span>
  );
}
