// The profile page's entry point: its root component and the queries the
// page needs, all keyed by the profile's vanity name.
import JSResource from "JSResource";
import ProfilePageHeaderQuery$parameters from "ProfilePageHeaderQuery$parameters";
import ProfilePageIntroQuery$parameters from "ProfilePageIntroQuery$parameters";
import ProfilePagePhotosQuery$parameters from "ProfilePagePhotosQuery$parameters";
import ProfilePageFriendsQuery$parameters from "ProfilePageFriendsQuery$parameters";
import ProfilePageComposerQuery$parameters from "ProfilePageComposerQuery$parameters";
import ProfilePageTimelineQuery$parameters from "ProfilePageTimelineQuery$parameters";
import { PROFILE_TIMELINE_INITIAL_COUNT } from "ProfileTimelineConfig";

const ProfilePageEntryPoint = {
  root: JSResource("ProfilePage.react"),
  getPreloadProps({ vanity }) {
    return {
      queries: {
        header: { parameters: ProfilePageHeaderQuery$parameters, variables: { vanity } },
        intro: { parameters: ProfilePageIntroQuery$parameters, variables: { vanity } },
        photos: { parameters: ProfilePagePhotosQuery$parameters, variables: { vanity } },
        friends: { parameters: ProfilePageFriendsQuery$parameters, variables: { vanity } },
        composer: { parameters: ProfilePageComposerQuery$parameters, variables: { vanity } },
        timeline: { parameters: ProfilePageTimelineQuery$parameters, variables: { vanity, count: PROFILE_TIMELINE_INITIAL_COUNT } },
      },
    };
  },
};

export default ProfilePageEntryPoint;
