import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIImage from "UIImage.react";

const styles = stylex.create({
  frame: { width: "100%", maxWidth: 1096, height: 400, marginInline: "auto", overflow: "hidden", backgroundColor: colors.glimmer, borderBottomLeftRadius: 12, borderBottomRightRadius: 12 },
  focus: (x, y) => ({ objectPosition: `${x * 100}% ${y * 100}%` }),
});

export default function ProfileCover({ user }) {
  const data = useFragment(
    graphql`
      fragment ProfileCover_user on User {
        cover_photo {
          photo {
            accessibility_caption
            image(width: 1096) {
              uri
              width
              height
            }
          }
          focus {
            x
            y
          }
        }
      }
    `,
    user,
  );
  const photo = data.cover_photo?.photo;
  const focus = data.cover_photo?.focus;
  return (
    <div data-testid="profile-cover" {...stylex.props(styles.frame)}>
      {photo?.image ? <UIImage src={photo.image.uri} width={1096} height={400} alt={photo.accessibility_caption ?? ""} fill xstyle={styles.focus(focus?.x ?? 0.5, focus?.y ?? 0.5)} /> : null}
    </div>
  );
}
